"use client"

import * as React from "react"
import {
  CodeIcon,
  FileTextIcon,
  ImageIcon,
  MicIcon,
  PaperclipIcon,
  SendIcon,
  XIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import { Kbd } from "@/components/ui/kbd"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Textarea } from "@/components/ui/textarea"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

type AttachmentKind = "image" | "document" | "code"

const ATTACH_OPTIONS: {
  kind: AttachmentKind
  label: string
  icon: React.ElementType
}[] = [
  { kind: "image", label: "Image", icon: ImageIcon },
  { kind: "document", label: "Document", icon: FileTextIcon },
  { kind: "code", label: "Code snippet", icon: CodeIcon },
]

const SUGGESTIONS = [
  "Summarize this page",
  "Fix grammar",
  "Write an email",
] as const

const ATTACH_LABEL: Record<AttachmentKind, string> = {
  image: "image.png",
  document: "brief.pdf",
  code: "snippet.tsx",
}

export default function PromptInput01() {
  const [value, setValue] = React.useState("")
  const [focused, setFocused] = React.useState(false)
  const [attachOpen, setAttachOpen] = React.useState(false)
  const [listening, setListening] = React.useState(false)
  const [attachment, setAttachment] = React.useState<AttachmentKind | null>(
    null
  )
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)

  const canSend = value.trim().length > 0 || attachment !== null

  const focusComposer = React.useCallback(() => {
    textareaRef.current?.focus()
  }, [])

  const handleSend = React.useCallback(() => {
    if (!canSend) return
    setValue("")
    setAttachment(null)
    setListening(false)
    focusComposer()
  }, [canSend, focusComposer])

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const applySuggestion = (suggestion: string) => {
    setValue(suggestion)
    focusComposer()
  }

  const pickAttachment = (kind: AttachmentKind) => {
    setAttachment(kind)
    setAttachOpen(false)
    focusComposer()
  }

  return (
    <TooltipProvider delayDuration={200}>
      <div className="mx-auto w-full max-w-3xl p-4 text-foreground md:p-8">
        <div className="flex w-full flex-col items-stretch gap-2">
          <div
            className={cn(
              "relative flex w-full flex-col rounded-[12px] border bg-card shadow-soft transition-[border-color,box-shadow]",
              focused || attachOpen
                ? "border-primary/50 ring-2 ring-primary/15"
                : "border-border/70 hover:border-border"
            )}
          >
            {attachment ? (
              <div className="flex items-center gap-2 px-4 pt-3">
                <span className="inline-flex max-w-full items-center gap-1.5 rounded-full border border-border/70 bg-muted/50 py-1 ps-2.5 pe-1 text-xs font-medium text-foreground">
                  {attachment === "image" ? (
                    <ImageIcon className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
                  ) : attachment === "document" ? (
                    <FileTextIcon className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
                  ) : (
                    <CodeIcon className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
                  )}
                  <span className="truncate" dir="ltr">
                    {ATTACH_LABEL[attachment]}
                  </span>
                  <button
                    type="button"
                    className="inline-flex size-6 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                    aria-label="Remove attachment"
                    onClick={() => {
                      setAttachment(null)
                      focusComposer()
                    }}
                  >
                    <XIcon className="size-3.5" aria-hidden />
                  </button>
                </span>
              </div>
            ) : null}

            <Textarea
              ref={textareaRef}
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onFocus={() => setFocused(true)}
              onBlur={() => setFocused(false)}
              onKeyDown={handleKeyDown}
              placeholder="Ask AI anything... (Use / for quick commands)"
              aria-label="Ask AI anything"
              rows={3}
              className={cn(
                "min-h-25 resize-none rounded-[12px] border-0 bg-transparent px-4 pt-4 pb-2 text-base shadow-none md:text-base",
                "focus-visible:border-transparent focus-visible:ring-0",
                "placeholder:text-muted-foreground/70"
              )}
            />

            <div
              className="flex items-center justify-between gap-3 px-3 pt-1 pb-3"
              onMouseDown={(e) => {
                // Keep the composer focused while using the toolbar.
                if (e.target instanceof HTMLElement && e.target.closest("button")) {
                  e.preventDefault()
                }
              }}
            >
              <div className="flex items-center gap-0.5">
                <Popover open={attachOpen} onOpenChange={setAttachOpen}>
                  <PopoverTrigger asChild>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon-xs"
                      aria-label="Attach file"
                      aria-expanded={attachOpen}
                      aria-haspopup="menu"
                      className="text-muted-foreground hover:text-foreground"
                    >
                      <PaperclipIcon className="size-4" aria-hidden />
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent
                    side="top"
                    align="start"
                    className="w-48 p-1"
                  >
                    <div className="flex flex-col gap-0.5" role="menu">
                      {ATTACH_OPTIONS.map((opt) => {
                        const Icon = opt.icon
                        return (
                          <Button
                            key={opt.kind}
                            type="button"
                            variant="ghost"
                            role="menuitem"
                            className="h-9 w-full justify-start gap-2 px-2.5 font-normal"
                            onClick={() => pickAttachment(opt.kind)}
                          >
                            <Icon
                              className="size-4 text-muted-foreground"
                              aria-hidden
                            />
                            {opt.label}
                          </Button>
                        )
                      })}
                    </div>
                  </PopoverContent>
                </Popover>

                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon-xs"
                      aria-label={
                        listening ? "Stop voice input" : "Voice input"
                      }
                      aria-pressed={listening}
                      className={cn(
                        "text-muted-foreground hover:text-foreground",
                        listening &&
                          "bg-destructive/10 text-destructive hover:bg-destructive/15 hover:text-destructive"
                      )}
                      onClick={() => setListening((v) => !v)}
                    >
                      <MicIcon
                        className={cn("size-4", listening && "animate-pulse")}
                        aria-hidden
                      />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent side="top">
                    {listening ? "Listening..." : "Voice input"}
                  </TooltipContent>
                </Tooltip>
              </div>

              <div className="flex items-center gap-3">
                <p className="hidden items-center gap-1.5 text-xs text-muted-foreground sm:flex">
                  <Kbd>Enter</Kbd>
                  <span>to send</span>
                </p>
                <Button
                  type="button"
                  size="sm"
                  className="gap-2 rounded-full px-4"
                  disabled={!canSend}
                  onClick={handleSend}
                >
                  Send
                  <SendIcon className="size-3.5 icon-dir" aria-hidden />
                </Button>
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-2 px-1">
            {SUGGESTIONS.map((suggestion) => (
              <Button
                key={suggestion}
                type="button"
                variant="outline"
                size="xs"
                className="h-7 rounded-full border-border/70 bg-card px-3 text-xs font-medium text-muted-foreground hover:text-foreground"
                onClick={() => applySuggestion(suggestion)}
              >
                {suggestion}
              </Button>
            ))}
          </div>
        </div>
      </div>
    </TooltipProvider>
  )
}
